def credit(name):
    if name=='lamassu':return '<a href="https://www.metmuseum.org/art/collection/search/322609" target="_blank" rel="noopener">Human-headed winged lion, Nimrud, c. 883-859 BCE. The Met, 32.143.2.</a> Public domain image; resized.'
    if name=='relief':return '<a href="https://www.metmuseum.org/art/collection/search/322610" target="_blank" rel="noopener">Relief panel, Nimrud, c. 883-859 BCE. The Met, 32.143.3.</a> Public domain image; resized.'
    if name=='khigga':return '<a href="https://commons.wikimedia.org/wiki/File:Khigga_dance_at_Assyrian_wedding.jpg" target="_blank" rel="noopener">Khigga dance at an Assyrian wedding, Yucalyptus, 2024.</a> <a href="https://creativecommons.org/publicdomain/zero/1.0/">CC0 1.0</a>; resized.'
    return '<a href="https://commons.wikimedia.org/wiki/File:04_Assyrian_folk_dance.jpg" target="_blank" rel="noopener">Assyrian folk dance at Taraz Fest, Yerevan, 2023. Volare42.</a> <a href="https://creativecommons.org/licenses/by-sa/4.0/" target="_blank" rel="noopener">CC BY-SA 4.0</a>. Resized and displayed with a crop; this image adaptation is available under the same licence.'
def source_item(s, numbering=None):
    date = H(s.get('checked') or 'not recorded')
    local = (' <a href="' + H(s['local_url']) + '">Read retained copy</a>') if s.get('local_url') else ''
    used = EVIDENCE['source_usage'].get(s['id'], []) if numbering is None else []
    linked = ', '.join(
        '<a href="' + link(slug) + '">' + H(AM[slug]['title']) + '</a>'
        for slug in used[:3]
    )
    more = (' <a href="/about/evidence/">See full register</a>' if len(used) > 3 else '')
    back_label = ' editorial guide: ' if len(used) == 1 else ' editorial guides: '
    backlinks = ('<small>Linked from ' + str(len(used)) + back_label + linked + more + '</small>') if used else ''
    return (f'<li id="source-{s["id"]}" class="source-item" data-source-search="{H((s["title"]+" "+s["publisher"]+" "+s["type"]).lower())}">'
            f'<span class="source-no">{numbering or icon("book")}</span><div><span class="eyebrow">{H(s["type"])}</span>'
            f'<h3><a href="{H(s["url"])}" target="_blank" rel="noopener">{H(s["title"])} {icon("external")}</a></h3>'
            f'<p>{H(s["publisher"])}</p><small>{H(s["access"])}. Recorded source check: {date}.{local}</small>'
            f'{backlinks}</div></li>')

