def section_reading_trail(article, section, source_numbers):
    """Display only explicitly mapped references - never infer evidence from article citations."""
    mapped = section_trail(article, section['title'])
    if not mapped:
        return ''
    primary = ', '.join(
        '<a href="' + reference_url(tuple(ref)) + '">' + H(reference_label(tuple(ref))) + '</a>'
        for ref in mapped.get('passages', [])
    )
    supporting = ', '.join(
        '<a href="#source-' + H(source_id) + '">[' + str(source_numbers[source_id]) + '] ' +
        H(SM[source_id]['publisher']) + '</a>'
        for source_id in mapped.get('sources', [])
    )
    details = []
    if primary:
        details.append('<p><strong>Scripture:</strong> ' + primary + '</p>')
    if supporting:
        details.append('<p><strong>Additional sources:</strong> ' + supporting + '</p>')
    return '<aside class="section-reading-trail" aria-label="Selected references for this section"><span class="eyebrow">Section reading trail</span>' + ''.join(details) + '</aside>'


def articles():
    for a in ARTICLES:
        if a.get('kind') == 'preserved_reference':
            reference_page(a)
            continue
        refs={s:i+1 for i,s in enumerate(a['sources'])}
        # Section trails are explicit and partial. The other sources remain article-level.
        citations=''.join(f'<a href="#source-{s}" class="citation" aria-label="Source {n}">[{n}]</a>' for s,n in refs.items())
        body=''.join(f'<section id="section-{i+1}"><h2>{H(s["title"])}</h2><p>{H(s["text"])}</p>{section_reading_trail(a,s,refs)}</section>' for i,s in enumerate(a['sections']))
        toc=''.join(f'<a href="#section-{i+1}">{H(s["title"])}</a>' for i,s in enumerate(a['sections']))
        if a.get('passages'):
            toc='<a href="#biblical-passages">Biblical primary passages</a>'+toc
        note=f'<aside class="article-note">{icon("book")}<p>{H(a["note"])}</p></aside>' if a.get('note') else ''
        visual=f'<figure class="article-visual"><img src="/assets/{a["image"]}.webp" alt="{H(image_alt(a["image"]))}" fetchpriority="high"><figcaption>{credit(a["image"])}</figcaption></figure>' if a.get('image') else ''
        related=''.join(card(AM[s]) for s in a['related'])
        main=f'''<main id="main"><div class="wrap article-header"><nav class="breadcrumbs" aria-label="Breadcrumb"><a href="/">Home</a><span>/</span><a href="/explore/">Explore</a><span>/</span><span>{H(a['category'])}</span></nav><span class="eyebrow">{H(a['category'])}</span><h1>{H(a['title'])}</h1><p class="article-deck">{H(a['summary'])}</p><div class="article-info">{badge('Sourced introduction')}<span>{minutes(a)} min read</span><span>Compiled 26 October 2026</span><button class="save text-action" data-save="{a['slug']}" aria-pressed="false">{icon('save')} <span>Save article</span></button><button class="copy-link text-action">{icon('copy')} Copy link</button></div></div><div class="wrap article-layout"><aside class="article-toc"><span class="eyebrow">In this article</span>{toc}<a href="#article-sources">Sources & further reading</a><a href="#related">Continue exploring</a></aside><article class="article-body">{visual}{note}{passage_panel(a)}{body}<div class="evidence-line"><span class="eyebrow">Evidence trail</span><p>This introduction draws on the following sources: {citations}. Section reading trails highlight selected references where a more precise relationship has been recorded. Unmapped passages and other references remain at article level; these trails are not a sentence-by-sentence verification. Editorial guidance is identified in the text.</p></div><section id="article-sources" class="article-sources"><span class="eyebrow">Go to the evidence</span><h2>Sources & further reading</h2><ul class="source-list">{''.join(source_item(SM[s],refs[s]) for s in a['sources'])}</ul></section><div class="article-review"><h3>A foundation to build on</h3><p>This introduction was compiled from the linked sources and has not received specialist peer review. It is intended as a route into further research. <a href="/governance/">Read how corrections and reviews are handled.</a></p><a href="/contribute/?type=correction&amp;article={a['slug']}">Prepare a correction or contribution {icon('arrow')}</a></div></article></div><section id="related" class="wrap section"><div class="section-top"><div><span class="eyebrow">A connected story</span><h2>Continue exploring.</h2></div></div><div class="article-grid">{related}</div></section></main>'''
        structured={'@context':'https://schema.org','@type':'Article','headline':a['title'],'description':a['summary'],'inLanguage':'en-AU','datePublished':'2026-10-26','dateModified':'2026-10-26','citation':[SM[s]['url'] for s in a['sources']]}
        extra='<script type="application/ld+json">'+json.dumps(structured).replace('<','\\u003c')+'</script>'
        if a.get('passages'):
            extra += '<link rel="stylesheet" href="/bible.css">'
        write(link(a['slug'])+'index.html',shell(a['title'],a['summary'],link(a['slug']),main,'',extra))

def reference_page(a):
    r=a['record']
    attribution=f"Text by Wikipedia contributors, retained under CC BY-SA 4.0. Revision {r['revision_id']}. Retrieved {r['retrieved_at']}. Reader formatting and punctuation adapted; media omitted. This is a preserved external reference, not an independently reviewed editorial article."
    main=f'<main id="main" class="wrap section narrow-page">{heading(H(a["category"]),H(a["title"]),"Preserved reference / Wikipedia contributors")}<aside class="article-note"><p>{H(attribution)} Entries about neighbouring societies, shared food or music, and related churches provide context; inclusion does not identify every person or tradition as Assyrian or exclusively Assyrian. For biblical accounts, <a href="/bible/">begin with the primary Scripture passages</a>; this retained text preserves the source authors and their perspectives.</p></aside><p><a href="{H(r["revision_url"])}">Original revision</a> / <a href="{H(r["history_url"])}">Authors and history</a> / <a href="{H(r["licence_url"])}">CC BY-SA 4.0 licence</a> / <a href="/archive/{r["raw_path"]}" download>Download retained source JSON</a></p><p class="muted">SHA-256: {r["sha256"]}</p><article class="article-body preserved-text">{a["html"]}</article></main>'
    write(link(a['slug'])+'index.html',shell(a['title'],a['summary'],link(a['slug']),main))

def timeline():
    items=''.join(f'<article class="timeline-event" data-era="{era}"><div class="event-date">{H(date)}</div><div class="event-content"><span class="eyebrow">{era}</span><h2><a href="{link(slug)}">{H(title)}</a></h2><p>{H(desc)}</p><a class="text-link" href="{link(slug)}">Read the story {icon("arrow")}</a><a class="event-source" href="{H(SM[src]["url"])}" target="_blank" rel="noopener">Source: {H(SM[src]["publisher"])} {icon("external")}</a></div></article>' for date,era,title,desc,slug,src in TIMELINE)
    filters=''.join(f'<button class="chip {"active" if i==0 else ""}" data-era-filter="{val}" aria-pressed="{"true" if i==0 else "false"}">{label}</button>' for i,(val,label) in enumerate([('all','All periods'),('Ancient','Ancient'),('Literary heritage','Literary heritage'),('Modern','Modern'),('Living culture','Living culture')]))
    main=f'<main id="main" class="wrap section narrow-page">{heading("THROUGH THE AGES","History has many chapters.","A selected chronology of places, writing, migration and cultural life. Follow each moment into its evidence.")}<div class="article-note"><p>These are selected moments across different histories. They do not imply an unchanged identity, language or institution across every interval. Period dates are approximate where indicated. <a class="text-link" href="/map/">Explore ancient Assyria on the interactive map &#8594;</a></p></div><div class="filter-chips" role="group" aria-label="Filter timeline">{filters}</div><div id="timeline-events">{items}</div><p class="muted" id="timeline-count" role="status">{len(TIMELINE)} selected moments</p></main>'
    write('/timeline/index.html',shell('Timeline','A selected chronology connecting ancient Assyria, Syriac literary heritage, migration and living culture.','/timeline/',main,'timeline'))

def sources():
    main=f'<main id="main" class="wrap section narrow-page">{heading("THE SOURCE LIBRARY","Go beyond the introduction.","A curated starting point for further research. Museum records, scholarship, archives, oral histories and community perspectives each offer a different kind of evidence.")}<div class="library-intro"><span>{len(SOURCES)} selected records</span><span>Source dates appear on individual records</span><a href="/catalogue.json" download>{icon("download")} Download catalogue</a></div><label class="search-field">{icon("search")}<input id="source-search" type="search" placeholder="Search sources by title, publisher or type" aria-label="Search sources"></label><p class="muted" id="source-count" role="status">Showing {len(SOURCES)} source records</p><ul class="source-list library-list">{"".join(source_item(s) for s in SOURCES)}</ul><div class="empty-state" id="source-empty" hidden><h2>No sources match that search.</h2><p>Try a publisher, collection or broader term.</p></div><aside class="collection-note"><span class="eyebrow">Access and evidence</span><p><a href="/about/evidence/">Explore the editorial evidence register</a> to see which guides cite each source and what has not been reviewed.</p><p>Publicly accessible does not mean freely reusable. Some book links provide only a public description, with full text access varying. Church and community sources are used for their own perspectives; they are not substitutes for independent scholarship on disputed claims. Publisher names do not imply partnership.</p></aside></main>'
    write('/sources/index.html',shell('Source library','Find the references behind the archive and explore institutional and community resources.','/sources/',main,'sources'))

def about():
    main=f'''<main id="main" class="wrap section narrow-page">{heading('THE PROJECT','An archive with a long horizon.','A source-led home for Assyrian knowledge, built to connect the ancient world with living people and the culture they carry forward.')}<div class="about-quote">A rich culture deserves<br>more than a footnote.</div><div class="prose"><h2>A foundation, with room to grow</h2><p>This expanded edition contains {len(EDITORIAL_ARTICLES)} original introductory articles and {len(REFERENCES)} locally preserved reference texts, six topic collections, a selected timeline and {len(SOURCES)} source records. It is a navigable research foundation, not a claim to contain every available fact or an academically reviewed encyclopaedia.</p><p>The working title is <em>Assyria | The Living Archive</em>. The project is independent and has no implied affiliation with the institutions it cites. Content is initially in English. Native-language translations and pronunciation material require qualified review before publication.</p><h2 id="editorial">How the archive earns trust</h2><ol class="principles"><li><strong>Begin with Scripture for biblical accounts.</strong> Treat the Bible as the primary source for the events and peoples it records. Cite book, chapter and verse before commentary, identify the translation and keep textual differences, genre and historical interpretation visible. <a href="/bible/">Read the biblical collection.</a></li><li><strong>Make claims traceable.</strong> Link introductions to named references and distinguish primary material, scholarship, testimony and institutional self-description.</li><li><strong>Keep the context.</strong> Ancient states, later religious traditions and modern ethnic identities need their own evidence. Do not fill historical gaps with certainty.</li><li><strong>Respect self-identification.</strong> Use the names people and institutions choose for themselves. Church affiliation, language and ethnicity are related but distinct.</li><li><strong>Show the limits.</strong> No invented population totals, unsupported casualty counts or claims of unchanged rituals across millennia. This edition is not specialist peer-reviewed.</li><li><strong>Preserve rights and consent.</strong> Write original summaries, link to copyrighted works, check each image licence and obtain permission for new interviews and family material.</li></ol><h2 id="historical-studies">New historical studies</h2><p>The original encyclopaedia now includes deeper reading routes through <a href="/articles/ashurnasirpal-ii/">Ashurnasirpal II</a>, <a href="/articles/tiglath-pileser-iii/">Tiglath-pileser III</a>, <a href="/articles/sargon-ii/">Sargon II</a>, <a href="/articles/sennacherib/">Sennacherib</a>, <a href="/articles/esarhaddon/">Esarhaddon</a> and <a href="/articles/ashurbanipal/">Ashurbanipal</a>. The supporting guides examine <a href="/articles/assyrian-governance/">government</a>, <a href="/articles/assyrian-deportation/">deportation</a>, <a href="/articles/imperial-languages/">languages</a>, <a href="/articles/assyrian-religious-life/">ancient religion</a>, the <a href="/articles/fall-of-nineveh/">fall of Nineveh</a> and <a href="/articles/post-imperial-assyria/">later regional history</a>. All are source-linked introductory studies, not specialist-reviewed histories.</p><h2 id="language-heritage">Language and cultural heritage</h2><p>Study <a href="/languages/">Syriac script, letterforms and living dialect recordings</a> in the dedicated language reference room. Eight new source-linked guides extend the archive through cuneiform interpretation, manuscripts, Unicode writing and named local Neo-Aramaic varieties. The references are documented, but no new pronunciation audio or specialist approval is claimed.</p><h2 id="community-heritage">Community testimony and cultural preservation</h2><p>The new <a href="/heritage/">community heritage and testimony room</a> links to already published migration accounts, language recordings, cultural practices and Assyrian community institutions. It includes original research guides and blank private-first documentation worksheets, with no public upload or invented participant consent. Pending editorial and rights approvals remain visible in Next Chapters.</p><h2 id="public-editorial-record">Editorial standards and revision record</h2><p>Read the <a href="/governance/">corrections policy, review roles and curated revision history</a> to see what published changes are documented, and what still requires independent subject review. The archive retains its <a href="/about/evidence/">separate claim-level evidence queue</a>. No unverified reviewer is represented as a completed specialist review.</p><h2 id="archive-preservation">Publication and long-term stewardship</h2><p>Our new <a href="/stewardship/">preservation and publication readiness page</a> explains checksum-backed site manifests, a tested offline recovery export and human release gates. The archive remains deliberately unindexed pending review. A local manifest does not mean that an independent or offsite backup has already been established.</p><h2 id="source-and-accessibility-audit">Source and accessibility auditing</h2><p>The <a href="/audit/">public audit report and methods</a> distinguish validated citation metadata from real external link availability and from scholarly verification. New automated checks cover navigation and form semantics across representative pages. Manual device, screen-reader and Syriac shaping reviews remain pending.</p><h2 id="historical-evidence-expansion">Historical and biblical evidence dossiers</h2><p>Eight new <a href="/dossiers/">historical evidence dossiers</a> compare passages in Kings, Isaiah, Chronicles, Nahum and Zephaniah with the Black Obelisk, Sennacherib's prisms, Lachish reliefs and the Babylonian Chronicle. Each section preserves its own source role, and new claim records remain queued for independent review.</p><h2 id="next-chapters">The next chapters</h2><p><a href="/about/expansion/">View the measured encyclopaedia expansion and preservation record.</a> <a href="/about/evidence/">Inspect the evidence and citation register.</a> <a href="/about/evidence/#claim-register-title">Review the claim-level evidence queue.</a> <a href="/governance/">Inspect the editorial and correction record.</a> The milestones below are maintained from a single roadmap file, including completed, in-progress, proposed and blocked work.</p></div>{render_roadmap()}<div class="prose"><h2>What needs people, not automation</h2><p>Specialist review is essential for contested history, language accuracy and religious interpretation. Community participation should broaden whose experiences are represented, with space for disagreement and clear attribution. Open contribution must come with moderation and a way to correct the record.</p><h2 id="privacy">Privacy and local storage</h2><p>This version has no account system or analytics script. Saved articles and your light/dark appearance preference are stored in this browser using local storage. The reading list can be cleared from its page; the appearance preference can be changed using the header toggle. The contribution form only prepares a local Markdown draft. It does not send email or publish submissions while the submission service is on hold. Any optional contact details are included only if you enter them in your local draft. Search runs locally after the article catalogue loads. Visiting a linked external source follows that provider\'s own privacy and access policies. Hosting may process ordinary request logs.</p><a class="button outline" href="/contribute/">Prepare a contribution {icon('arrow')}</a></div></main>'''
    write('/about/index.html',shell('About the archive','The scope, editorial principles and proposed expansion plan for Assyria | The Living Archive.','/about/',main))

def reading_list():
    main=f'<main id="main" class="wrap section">{heading("YOUR READING LIST","Keep a thread to follow.","Save articles while you explore, then return to the stories that caught your attention.")}<div class="results-line"><span id="reading-count" role="status"></span><button class="text-action" id="clear-saved">Clear reading list</button></div><div id="reading-grid" class="article-grid"></div><div class="empty-state" id="reading-empty" hidden>{icon("save")}<h2>Your next discoveries belong here.</h2><p>Use the bookmark button on any article to save it on this browser.</p><a href="/explore/" class="button outline">Explore the archive {icon("arrow")}</a></div><p class="local-note">Saved on this browser only. No account or synchronisation is used.</p></main>'
    write('/reading-list/index.html',shell('Reading list','Return to articles you have saved in this browser.','/reading-list/',main))

def contribute():
    main=f'''<main id="main" class="wrap section narrow-page">{heading('ADD TO THE STORY','Knowledge begins with someone.','Prepare a sourced article suggestion, correction or heritage contribution as a Markdown draft.')}<aside class="article-note">{icon('book')}<p>Email submissions are not currently enabled. This page creates a Markdown draft for you to keep on your device. Nothing is sent to the project editor or published.</p></aside><form id="contribution-form" class="contribution-form"><label>Contribution type<select name="type"><option>Article suggestion</option><option>Correction to an article</option><option>Personal or family history</option><option>Language or cultural knowledge</option><option>Image or media offer</option></select></label><label>Article or subject<input name="subject" id="contribution-subject" required maxlength="180" placeholder="A title, place, person or existing article"></label><label>Your name (optional)<input name="name" maxlength="120" autocomplete="name" placeholder="For future attribution or follow-up"></label><label>Contact email (optional, included in your local draft)<input name="email" type="email" maxlength="254" autocomplete="email" placeholder="Only if you want it included in the downloaded draft"></label><label>Your contribution<textarea name="body" rows="7" maxlength="10000" required placeholder="Describe the contribution, what can be checked and any uncertainties."></textarea></label><label>Sources or supporting records<textarea name="sources" rows="3" maxlength="5000" placeholder="Add URLs, publication details, object identifiers or document references."></textarea></label><label>Attribution and permissions<textarea name="permissions" rows="3" maxlength="3000" placeholder="Who owns any text or media? How would you like to be credited? Do not include sensitive personal details."></textarea></label><div class="contribution-actions"><button class="button solid" type="submit" id="download-draft">{icon('download')} Download Markdown draft</button></div><p class="muted" id="draft-status" role="status" aria-live="polite">Your draft remains in this browser until you download it or leave the page. No submission is sent.</p></form><div class="prose"><h2>What makes a useful contribution?</h2><p>Identify the place, time and community. Include sources another reader can check. For family material, confirm consent and ownership before offering it for publication. A personal recollection should be identified as testimony, and a proposed historical correction should explain the evidence behind it.</p><h2>Privacy and review</h2><p>For the <a href="/governance/">public correction policy and revision register</a>, read the editorial standards page. Filling this form is not a submitted complaint or an editor-approved correction.</p><p>All form entries are processed locally in your browser to create the downloadable Markdown file. Email delivery is on hold pending a project-specific, authorised sending arrangement. Do not assume that downloading a draft submits it for editorial review. No contribution is published automatically.</p><p>For interview planning, village histories and media permissions, use the <a href="/heritage/">heritage preservation room and blank worksheets</a>. Do not enter private family documents, addresses or sensitive third-party details into a public repository.</p></div></main>'''
    write('/contribute/index.html',shell('Prepare a contribution','Download a local Markdown contribution draft without sending personal data.','/contribute/',main))

def credits():
    main=f'<main id="main" class="wrap section narrow-page">{heading("CREDITS & REUSE","Heritage, with attribution.","Every displayed photograph has an identified source and reuse basis.")}<div class="prose"><h2>Photographs</h2><ul class="credit-list">{"".join(f"<li>{credit(n)}</li>" for n in ["lamassu","relief","khigga","folk-dance"])}</ul><h2>Biblical primary sources</h2><p>The complete public-domain World English Bible British Edition with Deuterocanon is retained by book. The <a href="/bible/">biblical collection</a> gives primary passage references, source hashes, the publisher notice and separately identified editorial guides. Quoted biblical wording and punctuation are preserved. Canonical status varies for the additional books.</p><h2>Content and sources</h2><p>Article introductions are original editorial summaries. The linked sources retain their own copyrights and terms. No complete copyrighted books, articles, songs or recipes are reproduced. Do not assume that an external image or translation is freely reusable because its subject is ancient.</p><h2>Typography and ornament</h2><p>Cormorant Garamond, Inter and Noto Sans Syriac are distributed under the SIL Open Font License. Licence texts are included with the site. The rosette is an original decorative mark for this working design and is not presented as an ancient artefact.</p><h2>Institutional independence</h2><p>Museums, universities, churches, broadcasters and community organisations are cited as sources. Their inclusion does not imply endorsement, collaboration or affiliation.</p><a href="/sources/" class="text-link">Browse all source records {icon("arrow")}</a></div></main>'
    write('/credits/index.html',shell('Credits and reuse','Image attribution, reuse information and source independence.','/credits/',main))

if __name__=='__main__':
    if OUT.is_symlink():
        raise ValueError('The generated dist directory must not be a symbolic link')
    if OUT.exists():
        shutil.rmtree(OUT)
    shutil.copytree(STATIC, OUT)
    shutil.copytree(ROOT / 'archive', OUT / 'archive')
    if (ROOT/'archive/encyclopaedia-references.json').exists():
        shutil.copyfile(ROOT/'archive/encyclopaedia-references.json', OUT/'archive/references.json')
    assert len(AM)==len(ARTICLES)
    for a in ARTICLES:
        assert all(s in SM for s in a['sources']), a['slug']
        assert all(s in AM for s in a['related']), a['slug']
    growth = measure_growth(ARTICLES)
    write('/encyclopaedia-growth.json',json.dumps(growth,indent=2)+'\n')
    write('/about/expansion/index.html',shell('Encyclopaedia expansion','Comparable article and text growth, source preservation and review status.','/about/expansion/',render_growth(heading,H,growth)))
    write('/evidence-index.json',json.dumps(EVIDENCE,ensure_ascii=False,indent=2)+'\n')
    write('/project-roadmap.json',json.dumps(PROJECT_ROADMAP,ensure_ascii=False,indent=2)+'\n')
    write('/heritage-records.json',json.dumps(HERITAGE_DATA,ensure_ascii=False,indent=2)+'\n')
    write('/editorial-revisions.json',json.dumps(EDITORIAL_DATA,ensure_ascii=False,indent=2)+'\n')
    write('/source-integrity-index.json',json.dumps(SOURCE_AUDIT,ensure_ascii=False,indent=2)+'\n')
    write('/about/evidence/index.html',shell('Evidence register','Source relationships and outstanding review limitations for the editorial encyclopaedia.','/about/evidence/',render_evidence(heading,H,EVIDENCE),extra='<link rel="stylesheet" href="/claim.css">'))
    validate_passages(EDITORIAL_ARTICLES)
    validate_languages(EDITORIAL_ARTICLES, SOURCES)
    validate_heritage(EDITORIAL_ARTICLES, SOURCES)
    validate_governance()
    home();explore();articles();timeline();sources();about();reading_list();contribute();credits()
    write('/glossary/index.html',shell('Glossary','Definitions and sourced reading routes for Assyrian history, languages, Scripture and preservation.','/glossary/',render_glossary(heading,H)))
    write('/languages/index.html',shell('Language and script reference','Syriac Unicode letters, Akkadian and Aramaic research, manuscript traditions and named dialect recordings.','/languages/',render_languages(heading,EDITORIAL_ARTICLES,SOURCES),'languages','<link rel="stylesheet" href="/languages.css">'))
    write('/heritage/index.html',shell('Community heritage and testimony','A public catalogue of Assyrian oral histories, cultural practices, community records and private-first preservation guidance.','/heritage/',render_heritage(heading,EDITORIAL_ARTICLES,SOURCES),'heritage','<link rel="stylesheet" href="/heritage.css"><script defer src="/heritage.js"></script>'))
    write('/governance/index.html',shell('Editorial governance and revisions','Public correction policy, independent review disclosure and a curated ledger of merged editorial changes.','/governance/',render_governance(heading),'governance','<link rel="stylesheet" href="/governance.css">'))
    write('/stewardship/index.html',shell('Publication and long-term stewardship','Documented site integrity, reproducible exports, recovery steps and publication readiness limitations.','/stewardship/',render_stewardship(heading),'stewardship','<link rel="stylesheet" href="/stewardship.css">'))
    write('/audit/index.html',shell('Source integrity and accessibility audit','Offline source metadata, accessibility automation coverage, method limitations and outstanding manual checks.','/audit/',render_audit(heading),'audit','<link rel="stylesheet" href="/audit.css">'))
    write('/dossiers/index.html',shell('Biblical and historical evidence dossiers','Eight primary-text comparisons with accessioned Assyrian monuments and inscriptions.','/dossiers/',render_dossiers(heading),'dossiers','<link rel="stylesheet" href="/dossiers.css">'))
    bible_paths = make_bible_pages(write, shell, heading, card, EDITORIAL_ARTICLES)
    write('/map/index.html', shell('Interactive historical map', 'Explore the growth and contraction of ancient Assyria with eleven dated map sketches, a draggable timeline and locally preserved geographical data.', '/map/', render_atlas(), 'map', '<link rel="stylesheet" href="/map.css"><script defer src="/map.js"></script>'))
    payload={'edition':'Research and preservation edition 01','compiled':'2026-10-26','articles':[{k:v for k,v in a.items() if k not in ('html','record','headings')} for a in ARTICLES],'sources':SOURCES,'topics':CATS}
    write('/catalogue.json',json.dumps(payload,ensure_ascii=False))
    write('/404.html',shell('Page not found','The requested page could not be found.','/404.html','<main id="main" class="wrap section empty-state"><h1>A path still to be written.</h1><p>This page is not in the archive.</p><a class="button outline" href="/explore/">Explore the articles</a></main>'))
    robots_text = 'User-agent: *\nAllow: /\n' if ALLOW_INDEXING else 'User-agent: *\nDisallow: /\n'
    if ALLOW_INDEXING:
        from xml.sax.saxutils import escape as xml_escape
        pages = ['/', '/explore/', '/timeline/', '/map/', '/glossary/', '/languages/', '/heritage/', '/governance/', '/stewardship/', '/audit/', '/dossiers/', '/about/expansion/', '/about/evidence/', '/sources/', '/about/', '/credits/'] + bible_paths + [link(a['slug']) for a in ARTICLES]
        sitemap = '<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'
        sitemap += ''.join('<url><loc>' + xml_escape(public_url(path)) + '</loc></url>' for path in pages)
        write('/sitemap.xml', sitemap + '</urlset>\n')
        robots_text += 'Sitemap: ' + public_url('/sitemap.xml') + '\n'
    write('/expansion-metrics.json', json.dumps(METRICS, indent=2))
    write('/robots.txt', robots_text)
    write('/.nojekyll', '')
    create_manifest(OUT, BASE_PATH, ALLOW_INDEXING)
    print(f'Generated {len(ARTICLES)} articles, {len(SOURCES)} source records and the Bible hub, verse index and chapter readers.')
